INSERT INTO exercises (owner_id,name,type,kind,group_key,subtitle,primary_muscles,secondary_muscles,steps,rest_sec_default,created_at) SELECT NULL,'Взятие на грудь и жим','weight_reps','cleanpress','shoulders','Всё тело · плечи','["shoulders", "glutes", "quads"]','["hamstrings", "traps", "triceps", "calves", "lowerback"]','["Штанга у голеней, спина ровная, хват чуть шире плеч.", "Резко выпрямите ноги и таз, подбросьте штангу и примите её на грудь.", "Выжмите штангу над головой, затем опустите на грудь и на пол."]',150,1794657461441 WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE owner_id IS NULL AND lower(name)=lower('Взятие на грудь и жим'));
INSERT INTO exercises (owner_id,name,type,kind,group_key,subtitle,primary_muscles,secondary_muscles,steps,rest_sec_default,created_at) SELECT NULL,'Отжимания с тягой гантелей','weight_reps','renegade','chest','Грудь · спина · пресс','["chest", "lats", "abs"]','["triceps", "shoulders", "biceps"]','["Упор лёжа на гантелях, стопы шире плеч.", "Отожмитесь, затем подтяните одну гантель к поясу.", "Опустите гантель и повторите другой рукой, не разворачивая таз."]',90,1794657461441 WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE owner_id IS NULL AND lower(name)=lower('Отжимания с тягой гантелей'));
INSERT INTO exercises (owner_id,name,type,kind,group_key,subtitle,primary_muscles,secondary_muscles,steps,rest_sec_default,created_at) SELECT NULL,'Берпи с подтягиванием','weight_reps','burpeepull','cardio','Всё тело · спина','["lats", "quads", "chest"]','["biceps", "triceps", "abs", "shoulders", "glutes"]','["Присядьте под турником и поставьте руки на пол.", "Отскочите в упор лёжа, отожмитесь и вернитесь в присед.", "Выпрыгните, возьмитесь за турник и подтянитесь."]',60,1794657461441 WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE owner_id IS NULL AND lower(name)=lower('Берпи с подтягиванием'));
INSERT INTO exercises (owner_id,name,type,kind,group_key,subtitle,primary_muscles,secondary_muscles,steps,rest_sec_default,created_at) SELECT NULL,'Турецкий подъём','weight_reps','getup','abs','Плечи · пресс · ягодицы','["shoulders", "abs", "glutes"]','["triceps", "quads", "hamstrings"]','["Лягте на спину, гиря в прямой руке над плечом.", "Поднимитесь на локоть, затем на ладонь и подведите ногу под себя.", "Встаньте через выпад, не опуская руку с гирей, и вернитесь обратно."]',90,1794657461441 WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE owner_id IS NULL AND lower(name)=lower('Турецкий подъём'));
INSERT INTO exercises (owner_id,name,type,kind,group_key,subtitle,primary_muscles,secondary_muscles,steps,rest_sec_default,created_at) SELECT NULL,'Присед, бицепс и жим','weight_reps','squatcurlpress','legs','Ноги · руки · плечи','["quads", "glutes", "biceps", "shoulders"]','["hamstrings", "triceps", "abs"]','["Присядьте с гантелями в опущенных руках.", "Встаньте и согните руки, поднимая гантели к плечам.", "Выжмите гантели над головой и вернитесь в исходное положение."]',90,1794657461441 WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE owner_id IS NULL AND lower(name)=lower('Присед, бицепс и жим'));
